import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  avatarBadgeClassName,
  avatarClassNameBySize,
  avatarFallbackClassName,
  avatarGroupClassName,
  avatarGroupCountClassName,
  avatarImageClassName,
} from "./view";
import type { AvatarSize } from "./view";

export type { AvatarSize };

export {
  avatarBaseClassName,
  avatarBadgeClassName,
  avatarClassNameBySize,
  avatarFallbackClassName,
  avatarGroupClassName,
  avatarGroupCountClassName,
  avatarImageClassName,
  avatarSizeClassNameBySize,
} from "./view";

export type AvatarStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  size?: AvatarSize | undefined;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type ImageViewConfig = Readonly<{
  src: string;
  alt: string;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type FallbackViewConfig = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type ViewConfig = Readonly<{
  fallback: string;
  src?: string | undefined;
  alt?: string | undefined;
  size?: AvatarSize | undefined;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type CountConfig = Readonly<{
  count: number;
  label?: string | undefined;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

export type BadgeViewConfig = Readonly<{
  children?: readonly Html[] | undefined;
  label?: string | undefined;
  className?: string | undefined;
  style?: AvatarStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  size = "Default",
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(avatarClassNameBySize(size), className)),
    ],
    children
  );
};

export const imageView = <ParentMessage>({
  src,
  alt,
  className,
  style,
}: ImageViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.img([
    h.Src(src),
    h.Alt(alt),
    ...(style === undefined ? [] : [h.Style(style)]),
    h.Class(classNames(avatarImageClassName, className)),
  ]);
};

export const fallbackView = <ParentMessage>({
  children,
  ariaLabel,
  className,
  style,
}: FallbackViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(avatarFallbackClassName, className)),
    ],
    children
  );
};

export const view = <ParentMessage>({
  fallback,
  src,
  alt,
  size = "Default",
  className,
  style,
}: ViewConfig): Html =>
  rootView<ParentMessage>({
    size,
    className,
    style,
    children:
      src === undefined
        ? [
            fallbackView<ParentMessage>({
              children: [html<ParentMessage>().span([], [fallback])],
            }),
          ]
        : [imageView<ParentMessage>({ src, alt: alt ?? fallback })],
  });

export const badgeView = <ParentMessage>({
  children = [],
  label,
  className,
  style,
}: BadgeViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      ...(label === undefined ? [h.AriaHidden(true)] : [h.AriaLabel(label)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(avatarBadgeClassName, className)),
    ],
    children
  );
};

export const groupView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [h.Class(classNames(avatarGroupClassName, className))],
    children
  );
};

export const countView = <ParentMessage>({
  count,
  label,
  className,
  style,
}: CountConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Class(classNames(avatarGroupCountClassName, className)),
      h.AriaLabel(label ?? `${count} more people`),
      h.Attribute("role", "img"),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    [`+${count}`]
  );
};

export type AvatarSize = "Small" | "Default" | "Large";

export const avatarBaseClassName =
  "relative inline-flex shrink-0 items-center justify-center rounded-full bg-gray-100 font-medium text-gray-700 ring-2 ring-white";

export const avatarImageClassName = "h-full w-full rounded-full object-cover";

export const avatarFallbackClassName =
  "flex h-full w-full items-center justify-center rounded-full bg-gray-100 text-gray-700";

export const avatarBadgeClassName =
  "absolute right-0 bottom-0 inline-flex h-3 w-3 items-center justify-center rounded-full border-2 border-white bg-green-600 text-[8px] text-white";

export const avatarGroupClassName = "flex items-center -space-x-2";

export const avatarGroupCountClassName =
  "relative inline-flex h-10 w-10 items-center justify-center rounded-full bg-gray-100 text-sm font-medium text-gray-700 ring-2 ring-white";

export const avatarSizeClassNameBySize = (
  size: AvatarSize = "Default"
): string => {
  if (size === "Small") {
    return "h-8 w-8 text-xs";
  }

  if (size === "Large") {
    return "h-12 w-12 text-base";
  }

  return "h-10 w-10 text-sm";
};

export const avatarClassNameBySize = (size: AvatarSize = "Default"): string =>
  `${avatarBaseClassName} ${avatarSizeClassNameBySize(size)}`;

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Avatar from "./index";

const imageSrc =
  "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 80 80'%3E%3Crect width='80' height='80' fill='%234f46e5'/%3E%3Ctext x='40' y='48' text-anchor='middle' font-size='24' font-family='Arial' fill='white'%3EAL%3C/text%3E%3C/svg%3E";

const view = (): Html => {
  const h = html<never>();

  return h.div(
    [h.Class("space-y-4")],
    [
      Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
      Avatar.view({ fallback: "GH", size: "Large" }),
      Avatar.rootView({
        children: [Avatar.fallbackView({ children: [h.span([], ["LT"])] })],
      }),
      Avatar.rootView({
        children: [
          Avatar.fallbackView({ children: [h.span([], ["CN"])] }),
          Avatar.badgeView({ label: "Online" }),
        ],
      }),
      Avatar.groupView([
        Avatar.view({ fallback: "AL", src: imageSrc, alt: "Ada Lovelace" }),
        Avatar.view({ fallback: "GH" }),
        Avatar.countView({ count: 3 }),
      ]),
    ]
  );
};

describe("Base UI Avatar registry view", () => {
  test("renders image, fallback, group, and count affordances", () => {
    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("img", { name: "Ada Lovelace" })).toExist(),
      Scene.expect(Scene.text("GH")).toExist(),
      Scene.expect(Scene.text("LT")).toExist(),
      Scene.expect(Scene.label("Online")).toExist(),
      Scene.expect(Scene.role("img", { name: "3 more people" })).toExist()
    );
  });
});
